import { useState } from "react";
import { Calendar } from "lucide-react";
import { useNavigate } from "react-router-dom";

export default function UploadScan() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: "",
    patientId: "",
    gender: "Female",
    date: "",
    image: null,
  });

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleImage = (e) =>
    setFormData({ ...formData, image: e.target.files[0] });

  const handleSubmit = (e) => {
    e.preventDefault();
    navigate("/results");
  };

  return (
    <div className="flex flex-col items-center justify-center p-6">
      <h1 className="text-xl font-semibold text-green-400 mb-4">MedVision AI Lab</h1>

      <div className="bg-gray-700 w-full max-w-md rounded-2xl p-6 shadow-lg">
        <select className="w-full p-2 rounded-lg bg-gray-600 mb-4">
          <option>Chest X-ray scanning</option>
          <option>Computed Tomography (CT)</option>
        </select>

        <label className="block text-center mb-3">
          <input
            type="file"
            onChange={handleImage}
            className="hidden"
            id="imageUpload"
          />
          <div
            onClick={() => document.getElementById("imageUpload").click()}
            className="cursor-pointer bg-gray-500 rounded-lg p-3"
          >
            {formData.image ? (
              <img
                src={URL.createObjectURL(formData.image)}
                alt="Uploaded"
                className="rounded-lg mx-auto"
              />
            ) : (
              <p>Drag and drop or choose image</p>
            )}
          </div>
        </label>

        <form onSubmit={handleSubmit} className="space-y-3">
          <input
            name="name"
            placeholder="Patient Name"
            className="w-full bg-gray-600 p-2 rounded-lg"
            value={formData.name}
            onChange={handleChange}
          />

          <input
            name="patientId"
            placeholder="Patient ID"
            className="w-full bg-gray-600 p-2 rounded-lg"
            value={formData.patientId}
            onChange={handleChange}
          />

          <select
            name="gender"
            value={formData.gender}
            onChange={handleChange}
            className="w-full bg-gray-600 p-2 rounded-lg"
          >
            <option>Female</option>
            <option>Male</option>
          </select>

          <div className="flex items-center bg-gray-600 rounded-lg p-2">
            <input
              type="date"
              name="date"
              className="bg-gray-600 flex-grow"
              onChange={handleChange}
            />
            <Calendar className="text-gray-400" />
          </div>

          <button className="bg-green-500 w-full p-2 rounded-lg mt-4 hover:bg-green-600">
            Scan
          </button>
        </form>
      </div>
    </div>
  );
}
